import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO


def task_func(url, table_id):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.HTTPError(str(e)) from e

    soup = BeautifulSoup(response.text, "html.parser")
    table = soup.find("table", id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all("tr")
    if not rows:
        return pd.DataFrame()

    first_row_cells = rows[0].find_all(["th", "td"])
    first_row_has_only_th = bool(rows[0].find_all("th")) and not rows[0].find_all("td")

    if first_row_has_only_th:
        headers = [cell.get_text(strip=True) for cell in first_row_cells]
        data_rows = rows[1:]
    else:
        headers = None
        data_rows = rows

    data = []
    for row in data_rows:
        cells = row.find_all(["th", "td"])
        if not cells:
            continue
        data.append([cell.get_text(strip=True) for cell in cells])

    if headers is not None:
        if not data:
            return pd.DataFrame(columns=headers)

        normalized_data = []
        for row in data:
            if len(row) < len(headers):
                row = row + [None] * (len(headers) - len(row))
            else:
                row = row[: len(headers)]
            normalized_data.append(row)

        return pd.DataFrame(normalized_data, columns=headers)

    return pd.DataFrame(data)
